mapper.select:
SELECT t.*
FROM task_assignment a
INNER JOIN learning_task t ON t.task_no = a.task_no

    a.status != 'cancelled'
    AND a.student_no = #{studentNo}

        AND a.course_code = #{courseCode}


        AND t.task_type = #{taskType}


        AND t.status = #{taskStatus}


        AND t.lesson_no = #{lessonNo}


ORDER BY a.assigned_at DESC, t.task_no DESC
